/* QR705-01: actual readings only. A blank department sheet never inherits sample identifiers. */
(()=>{
const words={scale:['QR705-01 磅秤日常點檢表','QR705-01 Daily scale inspection','QR705-01 Inspección diaria de básculas','QR705-01 Kiểm tra cân hằng ngày'],scWeight:['砝碼編號','Calibration weight ID','ID de pesa','Mã quả cân'],scSpec:['砝碼規格 (kg)','Weight specification (kg)','Especificación (kg)','Quy cách quả cân (kg)'],scMin:['允許下限 (kg)','Minimum (kg)','Mínimo (kg)','Giới hạn dưới (kg)'],scMax:['允許上限 (kg)','Maximum (kg)','Máximo (kg)','Giới hạn trên (kg)'],scNumber:['磅秤編號','Scale ID','ID de báscula','Mã cân'],scReading:['實際讀值 (kg)','Actual reading (kg)','Lectura real (kg)','Số đo thực tế (kg)'],scInspector:['點檢人員','Inspector','Inspector','Người kiểm tra'],scRepair:['維修記錄','Repair notes','Notas de reparación','Ghi chép sửa chữa'],scSupervisor:['主管','Supervisor','Supervisor','Quản lý'],scCustodian:['保管人','Custodian','Responsable','Người bảo quản'],scHelp:['每日使用前填寫實際讀值；△＝維修、X＝停用。超出範圍的數值以紅色提示。圖片按鈕只檢查所選日期的已填讀值並補上點檢人，不會產生重量。','Enter actual readings before daily use; △ = repair, X = stopped. Out-of-range readings appear red. The image button checks entered readings for the selected day and fills the inspector; it never generates weights.','Registre lecturas reales antes del uso; △ = reparación, X = detenido. Los valores fuera del rango aparecen rojos. El botón revisa lecturas del día seleccionado y completa el inspector, sin generar pesos.','Nhập số đo thực tế trước khi sử dụng; △ = sửa chữa, X = ngừng. Số ngoài giới hạn hiển thị đỏ. Nút hình ảnh kiểm tra số đã nhập của ngày chọn và điền người kiểm tra, không tạo số cân.'],scCheck:['檢查當日全部已填磅秤','Check all entered scales for the day','Revisar básculas del día','Kiểm tra tất cả cân đã nhập trong ngày'],scNeed:['請先填砝碼編號、磅秤編號、當日讀值與點檢人姓名；未完成的磅秤不會補填。','Enter weight and scale IDs, readings and inspector first. Incomplete scales are not filled.','Complete IDs, lecturas e inspector. No se rellenan básculas incompletas.','Nhập mã quả cân, mã cân, số đo và người kiểm tra. Không điền cân chưa đủ dữ liệu.'],scChecked:['當日已填讀值已檢查並補上點檢人；異常讀值仍保留，請確認後儲存。','Entered readings checked and inspector filled; abnormal readings are retained. Review and save.','Lecturas revisadas e inspector completado; se conservan anomalías. Revise y guarde.','Đã kiểm tra số đã nhập và điền người kiểm tra; giữ nguyên số bất thường. Kiểm tra rồi lưu.'],scSaved:['資料已儲存','Saved','Guardado','Đã lưu'],scError:['未儲存。請檢查編號、日期與點檢人；若資料已被更新，請重新讀取後再修改。','Not saved. Check IDs, dates and inspectors. If changed by another user, reload before editing.','No guardado. Revise IDs, fechas e inspectores. Si otro usuario cambió datos, recargue antes de editar.','Chưa lưu. Kiểm tra mã, ngày và người kiểm tra. Nếu người khác đã cập nhật, tải lại trước khi sửa.'],scLeave:['尚有未儲存的磅秤資料，確定離開？','Leave unsaved scale readings?','¿Salir sin guardar lecturas?','Rời đi khi chưa lưu số cân?']};
for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
let ctx='',dept='',month='',selected=1,record=null,doc=null,dirty=false,busy=false,ticket=0,message='';
const onPage=()=>view==='scale';
const scope=()=>[activeCountry,countryGeneration,profile?.account_id].join(':');
const ds=()=>data.departments.filter(d=>d.is_active!==false&&accessCan(d.id,'scale'));
const blank=()=>({weightId:'',spec:'2.000',minimum:'1.995',maximum:'2.000',notes:'',supervisor:'',custodian:'',rows:Array.from({length:8},()=>({number:'',days:{}}))});
const writable=()=>accessCan(dept,'scale',record?'edit':'create');
const dayDate=d=>month+'-'+String(d).padStart(2,'0');
const future=d=>dayDate(d)>inspectionDay();
const dayCount=()=>new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();
const bad=v=>!['','△','X'].includes(v)&&(!/^\d+(\.\d{1,6})?$/.test(v)||Number(v)<Number(doc.minimum)||Number(v)>Number(doc.maximum));
function leave(){return !busy&&(!dirty||confirm(t('scLeave')));}
const priorRender=render;render=function(){priorRender();if(!profile||!activeCountry||!accessAny('scale'))return;const parent=$('.side details[data-section="field"] .nav-section-items');if(!parent)return;const b=document.createElement('button');b.className='nav'+(onPage()?' active':'');b.dataset.view='scale';b.innerHTML='▶ '+txt('scale');b.onclick=()=>{view='scale';render();};parent.append(b);if(onPage())parent.parentElement.open=true;};
const priorContent=renderContent;renderContent=function(){if(onPage()&&profile&&activeCountry){draw();return;}ticket++;priorContent();};
document.addEventListener('click',e=>{if(!onPage()||(!dirty&&!busy))return;const b=e.target.closest('.side [data-view],#switchCountry,#loginButton,#refresh');if(b&&!leave()){e.preventDefault();e.stopImmediatePropagation();}else if(b){dirty=false;doc=null;}},true);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function request(body){const original=scope(),r=await fetch('https://dpenlftkwzqwhgpvutwk.supabase.co/functions/v1/scale-checklist-api',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+localStorage.getItem('inspection_token')},body:JSON.stringify({...body,country_code:activeCountry,department_id:dept,month})});const result=await r.json();if(scope()!==original)throw Error('country_changed');if(!r.ok)throw Error(result.error);return result;}
async function draw(){
 if(ctx!==scope()){ctx=scope();dept='';month=inspectionDay().slice(0,7);selected=Number(inspectionDay().slice(8));doc=null;dirty=false;}
 if(!ds().some(d=>d.id===dept))dept=ds().find(d=>d.id===profile.department_id)?.id||ds()[0]?.id||'';
 $('.page-title h1').innerHTML=txt('scale');
 if(!dept){$('#content').innerHTML=txt('accessNoRights');return;}
 $('#content').innerHTML=`<section class="scale-page"><div class="filter-row sc-toolbar"><label>${txt('department')}<select class="select" id="scDept">${ds().map(d=>`<option value="${esc(d.id)}" ${dept===d.id?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></label><label>${txt('month')}<input class="select" id="scMonth" type="month" min="2000-01" max="${inspectionDay().slice(0,7)}" value="${month}"></label><button class="btn secondary" id="scReload">${txt('envReload')}</button><button class="btn secondary" id="scPrint">${txt('envPrint')}</button></div><p id="scMessage" role="status">${esc(message)}</p><div id="scBody"></div></section>`;
 for(const[id,change]of [['scDept',v=>dept=v],['scMonth',v=>month=v]])$('#'+id).onchange=e=>{if(!leave()){draw();return;}if(id==='scMonth'&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){draw();return;}change(e.target.value);selected=1;doc=null;dirty=false;message='';draw();};
 $('#scReload').onclick=()=>{if(leave()){doc=null;dirty=false;draw();}};
 $('#scPrint').onclick=()=>{document.body.classList.add('printing-scale');try{window.print();}finally{document.body.classList.remove('printing-scale');}};
 if(!doc){const n=++ticket;busy=true;try{const r=await request({action:'get'});if(n!==ticket||!onPage())return;record=r.record;doc=structuredClone(record?.document||r.template||blank());message='';}catch{if(n===ticket)$('#scMessage').innerHTML=txt('networkProblem');return;}finally{if(n===ticket)busy=false;}}
 body();
}
function body(){
 const days=dayCount(),editable=writable();selected=Math.min(selected,days);
 $('#scBody').innerHTML=`<p class="notice sc-toolbar">${txt('scHelp')}</p><article class="sc-paper"><header><h2>${txt('scale')}</h2>${powerCheckButton('scCheck','id="scCheck" '+(!editable?'disabled':''))}</header><p>${esc(nameOf(ds().find(d=>d.id===dept)))} · ${month}</p><div class="sc-meta">${[['weightId','scWeight'],['spec','scSpec'],['minimum','scMin'],['maximum','scMax']].map(([key,label])=>`<label>${txt(label)}<input class="select" data-sc-header="${key}" maxlength="100" value="${esc(doc[key])}" ${editable?'':'disabled'}></label>`).join('')}</div><div class="filter-row sc-toolbar"><label>${txt('inspectionDate')}<select class="select" id="scDay">${Array.from({length:days},(_,i)=>`<option value="${i+1}" ${selected===i+1?'selected':''}>${dayDate(i+1)}</option>`).join('')}</select></label><label>${txt('scInspector')}<input class="select" id="scName" maxlength="100"></label></div><div class="sc-scroll"><table class="sc-table"><colgroup><col style="width:155px">${'<col style="width:72px">'.repeat(days)}</colgroup><thead><tr><th>${txt('scNumber')}</th>${Array.from({length:days},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${doc.rows.map((r,i)=>`<tr><th rowspan="2"><label>${txt('scNumber')}<input class="select" maxlength="100" data-sc-number="${i}" value="${esc(r.number)}" ${editable?'':'disabled'}></label></th>${Array.from({length:days},(_,j)=>{const value=r.days[j+1]?.value||'';return `<td class="${bad(value)?'sc-abnormal':''}"><input aria-label="${esc(t('scReading')+' '+(i+1)+' / '+(j+1))}" data-sc-value="${i}:${j+1}" value="${esc(value)}" maxlength="20" inputmode="decimal" ${editable&&!future(j+1)?'':'disabled'}></td>`;}).join('')}</tr><tr>${Array.from({length:days},(_,j)=>`<td><input aria-label="${esc(t('scInspector')+' '+(i+1)+' / '+(j+1))}" data-sc-inspector="${i}:${j+1}" value="${esc(r.days[j+1]?.inspector||'')}" maxlength="100" ${editable&&!future(j+1)?'':'disabled'}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="sc-footer">${[['notes','scRepair'],['supervisor','scSupervisor'],['custodian','scCustodian']].map(([key,label])=>`<label>${txt(label)}<textarea data-sc-header="${key}" maxlength="${key==='notes'?4000:100}" ${editable?'':'disabled'}>${esc(doc[key]||'')}</textarea></label>`).join('')}</div><p class="sc-code">QR705-01-A</p></article><button class="btn primary sc-toolbar" id="scSave" ${editable?'':'disabled'}>${txt('save')}</button>`;
 $$('[data-sc-header]').forEach(x=>x.oninput=()=>{doc[x.dataset.scHeader]=x.value;dirty=true;});$$('[data-sc-number]').forEach(x=>x.oninput=()=>{doc.rows[+x.dataset.scNumber].number=x.value.trim();dirty=true;});
 for(const field of ['value','inspector'])$$('[data-sc-'+field+']').forEach(x=>x.oninput=()=>{const[i,d]=x.getAttribute('data-sc-'+field).split(':');const r=doc.rows[i];r.days[d]={...r.days[d],[field]:x.value.trim()};if(!r.days[d].value&&!r.days[d].inspector)delete r.days[d];dirty=true;if(field==='value')x.parentElement.classList.toggle('sc-abnormal',bad(x.value.trim()));});
 $('#scDay').onchange=e=>selected=+e.target.value;
 $('#scCheck').onclick=()=>{if(busy||!editable)return;const name=$('#scName').value.trim(),filled=doc.rows.filter(r=>r.days[selected]?.value);if(future(selected)||!name||!doc.weightId.trim()||!filled.length||filled.some(r=>!r.number||!(/^\d+(\.\d{1,6})?$/.test(r.days[selected].value)||['△','X'].includes(r.days[selected].value)))){$('#scMessage').innerHTML=txt('scNeed');return;}for(const r of filled)if(!r.days[selected].inspector)r.days[selected].inspector=name;dirty=true;body();$('#scMessage').innerHTML=txt('scChecked');};
 $('#scSave').onclick=async()=>{if(busy||!editable)return;busy=true;$('#scSave').disabled=true;try{const r=await request({action:'save',revision:record?.revision||0,document:doc});record=r.record;dirty=false;$('#scMessage').innerHTML=txt('scSaved');}catch{$('#scMessage').innerHTML=txt('scError');}finally{busy=false;$('#scSave').disabled=false;}};
}
})();
